var player_stats := {
    "fear": 0.0,
    "stamina": 100.0,
    "battery": 100.0,
}

func spotting_range() -> float:
    if is_flashlight_on:
        return 20.0
    else:
        return 8.0

if is_hiding:
    return
if is_looking_at_monster and distance_to_player <= hear_distance:
    raise_fear(8.0 * delta)

@export var panic_threshold := 75.0

if fear >= panic_threshold:
    monster_speed = 4.0
else:
    monster_speed = 2.0

func flicker_lights(times: int) -> void:
    for i in range(times):
        hallway_light.visible = not hallway_light.visible
        await get_tree().create_timer(0.08).timeout
    hallway_light.visible = true

for sound in heard_sounds:
    if sound.volume > threshold:
        investigate(sound.position)
        break

var i := 0
while i < hiding_spots.size():
    if hiding_spots[i].is_open:
        return hiding_spots[i]
    i += 1
return null

for body in nearby_bodies:
    if body == self or body.is_hiding:
        continue
    investigate(body.global_position)
    break

func _ready() -> void:
    toggle_flashlight()  # starts off until the player presses the key

func _process(delta: float) -> void:
    if is_flashlight_on:
        flashlight_battery = maxf(flashlight_battery - drain_rate * delta, 0.0)

func toggle_flashlight() -> void:
    is_flashlight_on = not is_flashlight_on
    flashlight_light.visible = is_flashlight_on

func raise_fear(amount: float) -> void:
    fear = clampf(fear + amount, 0.0, max_fear)
    fear_changed.emit(fear)

func toggle_flashlight() -> void:
    is_flashlight_on = not is_flashlight_on
    flashlight_toggled.emit(is_flashlight_on)

func _ready() -> void:
    fear_changed.connect(_on_fear_changed)
    flashlight_toggled.connect(_on_flashlight_toggled)

func _on_fear_changed(new_fear: float) -> void:
    # Later: update a fear bar on the screen.
    pass

func _on_flashlight_toggled(is_on: bool) -> void:
    flashlight_light.visible = is_on

func raise_fear(amount: float) -> void:
    fear = clampf(fear + amount, 0.0, max_fear)
    fear_changed.emit(fear)

if is_flashlight_on and is_looking_at_monster:
    raise_fear(8.0 * delta)
elif mic_volume > threshold and distance <= hear_distance:
    player_spotted.emit()

@export var hear_distance := 15.0
@export var fear_step := 5.0
@export var drain_rate := 4.0
